import java.util.*;

class Solution {
  public String[] expand(String s) {
    List<List<Character>> groups = new ArrayList<>();
    for (int i = 0; i < s.length(); i++) {
      List<Character> g = new ArrayList<>();
      if (s.charAt(i) == '{') {
        for (i++; s.charAt(i) != '}'; i++) if (s.charAt(i) != ',') g.add(s.charAt(i));
      } else g.add(s.charAt(i));
      Collections.sort(g);
      groups.add(g);
    }
    List<String> res = new ArrayList<>();
    build(groups, 0, new StringBuilder(), res);
    return res.toArray(new String[0]);
  }

  private void build(List<List<Character>> groups, int i, StringBuilder sb, List<String> res) {
    if (i == groups.size()) {
      res.add(sb.toString());
      return;
    }
    for (char c : groups.get(i)) {
      sb.append(c);
      build(groups, i + 1, sb, res);
      sb.setLength(sb.length() - 1);
    }
  }
}
